KG42.register("slice-clusters-10ee9e0a3ecab305d8f4c5e7",{"id":"15-multiagent_reverse_auction::v142-d-K003","paper":"15-multiagent_reverse_auction","title":"Allocation and execution of qualified supply and conditional utility-grid supplementary purchase","source_pointer":"/clusters/63","node_ids":["COMP-334f35169e6933ed","COMP-443a9bf9853dcd78","COMP-b646a091517c6af0","COMP-efa6e37c97477e8a","COMP-8ae9e2dee736e7c9","COMP-143910e2088c2223"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R004","15-multiagent_reverse_auction::v141-c-R007","15-multiagent_reverse_auction::v141-c-R002","15-multiagent_reverse_auction::v141-c-R005","15-multiagent_reverse_auction::v141-c-R008"],"visible_rule_refs":["15-multiagent_reverse_auction::v141-c-R004","15-multiagent_reverse_auction::v141-c-R007","15-multiagent_reverse_auction::v141-c-R002","15-multiagent_reverse_auction::v141-c-R005","15-multiagent_reverse_auction::v141-c-R008"],"suppressed_rule_refs":[],"edges":[{"global_edge_id":"S-1171a97eef6b23ca","source":"COMP-334f35169e6933ed","target":"COMP-443a9bf9853dcd78","type":"links","assertion_ids":["15-multiagent_reverse_auction::v141-c-R004::E::v141-c-R004-E001"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R004"],"internal":false},{"global_edge_id":"S-7cac7e7e05679c72","source":"COMP-b646a091517c6af0","target":"COMP-443a9bf9853dcd78","type":"links","assertion_ids":["15-multiagent_reverse_auction::v141-c-R004::E::v141-c-R004-E002"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R004"],"internal":false},{"global_edge_id":"S-cafb53c793447e46","source":"COMP-443a9bf9853dcd78","target":"COMP-efa6e37c97477e8a","type":"links","assertion_ids":["15-multiagent_reverse_auction::v141-c-R007::E::v141-c-R007-E001"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R007"],"internal":false},{"global_edge_id":"S-433138ef4b5da00c","source":"COMP-443a9bf9853dcd78","target":"COMP-efa6e37c97477e8a","type":"precedes","assertion_ids":["15-multiagent_reverse_auction::v141-c-R007::E::v141-c-R007-E002"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R007"],"internal":false},{"global_edge_id":"S-d11dbb18b1173504","source":"COMP-b646a091517c6af0","target":"COMP-efa6e37c97477e8a","type":"links","assertion_ids":["15-multiagent_reverse_auction::v141-c-R007::E::v141-c-R007-E003"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R007"],"internal":false},{"global_edge_id":"S-b96435de609d3cf9","source":"COMP-efa6e37c97477e8a","target":"COMP-8ae9e2dee736e7c9","type":"conditional_on","assertion_ids":["15-multiagent_reverse_auction::v141-c-R007::E::v141-c-R007-E004"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R007"],"internal":false},{"global_edge_id":"S-ab5b64120bda1642","source":"COMP-b646a091517c6af0","target":"COMP-143910e2088c2223","type":"links","assertion_ids":["15-multiagent_reverse_auction::v141-c-R002::E::v141-c-R002-E001"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R002"],"internal":false},{"global_edge_id":"S-ff6c33e3f58ddff9","source":"COMP-334f35169e6933ed","target":"COMP-b646a091517c6af0","type":"links","assertion_ids":["15-multiagent_reverse_auction::v141-c-R005::E::v141-c-R005-E001"],"rule_refs":["15-multiagent_reverse_auction::v141-c-R005"],"internal":false}],"unresolved_rule_refs":[],"interface_annotations":[{"connection_id":"v142-d-K003-L01","from_chain_id":"v141-c-R002","to_chain_id":"v141-c-R004","kind":"functional_coupling","from_refs":["v141-c-R002::phi::v141-c-R002-C001"],"to_refs":["v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C004","v141-c-R004::phi::v141-c-R004-C005"],"evidence_ids":["v141-b-g01-E12","v141-b-g01-E16","v141-b-g01-E19"],"rationale":"The estimated procurement demand for the same hour becomes the object of the qualified-supply coverage check and the residual-demand allocation; the two chains have no typed demand variable that could be merged separately."},{"connection_id":"v142-d-K003-L02","from_chain_id":"v141-c-R005","to_chain_id":"v141-c-R004","kind":"functional_coupling","from_refs":["v141-c-R005::phi::v141-c-R005-C001","v141-c-R005::phi::v141-c-R005-C002"],"to_refs":["v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C003"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E19"],"rationale":"The available-power bids received by the aggregator provide information for the subsequent check of qualified suppliers' coverage capability, and the two chains also retain a common verbal procurement objective; eligibility is not inferred from bid receipt, and the power and energy wording is not rewritten into the same optimization formula."},{"connection_id":"v142-d-K003-L03","from_chain_id":"v141-c-R008","to_chain_id":"v141-c-R004","kind":"complementary_scope","from_refs":["v141-c-R008::phi::v141-c-R008-C001"],"to_refs":["v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C004","v141-c-R004::phi::v141-c-R004-C005"],"evidence_ids":["v141-b-g01-E04","v141-b-g01-E14","v141-b-g01-E19"],"rationale":"When a single seller cannot meet demand, multiple qualified sellers are permitted, which is complementary to the allocation scope in which other suppliers bear the residual demand after the first supplier is insufficient; the permission itself does not define the ordering of the first and second suppliers."},{"connection_id":"v142-d-K003-L04","from_chain_id":"v141-c-R004","to_chain_id":"v141-c-R007","kind":"functional_coupling","from_refs":["v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C004","v141-c-R004::phi::v141-c-R004-C005"],"to_refs":["v141-c-R007::phi::v141-c-R007-C001","v141-c-R007::phi::v141-c-R007-C002","v141-c-R007::phi::v141-c-R007-C004"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E14","v141-b-g01-E19","v141-b-g01-E20"],"rationale":"The allocation section determines the use of the power references, and the execution section specifies that these references are communicated to qualified bidding agents and the executor and implemented. This connects the allocation output with execution responsibility and does not create a separate temporal or quantitative scientific edge."},{"connection_id":"v142-d-K003-L05","from_chain_id":"v141-c-R004","to_chain_id":"v141-c-R007","kind":"complementary_scope","from_refs":["v141-c-R004::phi::v141-c-R004-C002"],"to_refs":["v141-c-R007::phi::v141-c-R007-C003","v141-c-R007::phi::v141-c-R007-C006"],"evidence_ids":["v141-b-g01-E21"],"rationale":"The branch with participation and insufficient total supply appears in the allocation chain as a procurement arrangement and in the execution chain as DER procurement plus utility-grid supplementary purchase; only this branch is combined and it is not conflated with full external purchase when there is no participation."}],"annotation_policy":"Original D connections are annotations, not additional S edges.","empty_after_chain_suppression":false});
